312	    /** The household size at or above which an owner earns the household membership points. */
313	    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;
314	
315	    /** The month (1 July) on which the fiscal year begins. */
316	    public static final int FISCAL_YEAR_START_MONTH = 7;
317	
318	    /**
319	     * The number of elapsed fiscal years at or above which an owner earns the tenure membership
320	     * points.
321	     */
322	    public static final long MEMBERSHIP_TENURE_FISCAL_YEARS = 1;
323	
324	    /**
325	     * The fiscal year (as a full four-digit number) that {@code date} falls in, where the fiscal
326	     * year begins on 1 July and is labelled by the calendar year in which it ends: a date on or
327	     * after 1 July belongs to the next calendar year's fiscal year.
328	     */
329	    public static int fiscalYearOf(LocalDate date) {
330	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
331	    }
332	
333	    /**
334	     * The fiscal year carried by the owner's {@link #getMemberId() memberId}, formatted
335	     * {@code 'FY<YY>'} where YY is the two-digit fiscal-year (FY) segment of the memberId — the two
336	     * characters following the {@code <REGION>} prefix (see {@link Region#regionOfMemberId(String)}).
337	     * Null when no memberId has been assigned.
338	     */
339	    public String getFiscalYear() {
340	        if (this.memberId == null) {
341	            return null;
342	        }
343	        int start = Region.regionOfMemberId(this.memberId).length();
344	        if (this.memberId.length() < start + 2) {
345	            return null;
346	        }
347	        return "FY" + this.memberId.substring(start, start + 2);
348	    }
349	
350	    /**
351	     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
352	     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
353	     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
354	     * the owner's tenure (fiscal years elapsed since its {@code registrationDate}) is at least
355	     * {@value #MEMBERSHIP_TENURE_FISCAL_YEARS}.
356	     */
357	    public int getMembershipPoints() {
358	        int points = 0;
359	        if (this.email != null && !this.email.isEmpty()) {
360	            points += 2;
361	        }
362	        if (this.namesakeCount != null && this.namesakeCount == 0) {
363	            points += 1;
364	        }
365	        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
366	            points += 2;
367	        }
368	        if (this.registrationDate != null
369	                && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate))
370	                        >= MEMBERSHIP_TENURE_FISCAL_YEARS) {
371	            points += 3;
372	        }
373	        return points;
374	    }
375	
376	    /**
377	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
378	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points, then capped by the
379	     * {@link #getMembershipLevelCap() membership level cap} when one was captured at creation time.
380	     */
381	    public int getMembershipLevel() {
382	        int level = computeMembershipLevel();
383	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
384	            return this.membershipLevelCap;
385	        }
386	        return level;
387	    }
388	
389	    /**
390	     * The uncapped membership level derived purely from {@link #getMembershipPoints()}: 1 for 0-1
391	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
392	     */
393	    private int computeMembershipLevel() {
394	        int points = getMembershipPoints();
395	        if (points >= 6) {
396	            return 4;
397	        }
398	        if (points >= 4) {
399	            return 3;
400	        }
401	        if (points >= 2) {
402	            return 2;
403	        }
404	        return 1;
405	    }
406	
407	    /**
408	     * The owner's marketing segment formatted {@code '<TIER>_<AREA>'}, one of
409	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
410	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when {@link #getMembershipLevel()} is 3
411	     * or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality (the
412	     * region of its {@code memberId}, see {@link Region#regionOfMemberId(String)}) is a known
413	     * region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
414	     */
415	    public String getOwnerSegment() {
416	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
417	        String area = Region.isKnownRegion(Region.regionOfMemberId(this.memberId))
418	                ? "METRO" : "REGIONAL";
419	        return tier + "_" + area;
420	    }
421	
422	    public Integer getMembershipLevelCap() {
423	        return this.membershipLevelCap;
424	    }
425	
426	    public void setMembershipLevelCap(Integer membershipLevelCap) {
427	        this.membershipLevelCap = membershipLevelCap;
428	    }
429	
430	    /**
431	     * The derived identity key used to detect duplicate owners: the lower-case SHA-256 hex digest
432	     * over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the
433	     * telephone is already normalized to E.164 and the email is lower-cased. Two owners are
434	     * duplicates only when their whole identity keys are equal. Because the telephone is part of the
435	     * key, two owners with the same {@code lastName} and {@code postcode} but different telephones
436	     * have different keys and are both allowed (they are instead flagged as a soft match).
437	     */
438	    public String getIdentityKey() {
439	        String tel = this.telephone == null ? "" : this.telephone;
440	        String mail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
441	        String soundex = Soundex.encode(this.getLastName());
442	        return Sha256Hex.lowerHex(tel + "|" + mail + "|" + soundex);
443	    }
444	
445	    public boolean isSharesHousehold() {
446	        return this.sharesHousehold;
447	    }
448	
449	    public void setSharesHousehold(boolean sharesHousehold) {
450	        this.sharesHousehold = sharesHousehold;
451	    }
452	
453	    public int getHouseholdSize() {
454	        return this.householdSize;
455	    }
456	
457	    public void setHouseholdSize(int householdSize) {
458	        this.householdSize = householdSize;
459	    }
460	
461	    protected Set<Pet> getPetsInternal() {
462	        if (this.pets == null) {
463	            this.pets = new HashSet<>();
464	        }
465	        return this.pets;
466	    }
467	
468	    protected void setPetsInternal(Set<Pet> pets) {
469	        this.pets = pets;
470	    }
471	
472	    public List<Pet> getPets() {
473	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
474	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
475	        return Collections.unmodifiableList(sortedPets);
476	    }
477	
478	    public void setPets(List<Pet> pets) {
479	        this.pets = new HashSet<>(pets);
480	    }
481	
482	    public void addPet(Pet pet) {
483	        getPetsInternal().add(pet);
484	        pet.setOwner(this);
485	    }
486	
487	    /**
488	     * Return the Pet with the given name, or null if none found for this Owner.
489	     *
490	     * @param name to test
491	     * @return true if pet name is already in use
492	     */
493	    public Pet getPet(String name) {
494	        return getPet(name, false);
495	    }
496	
497	    /**
498	     * Return the Pet with the given name, or null if none found for this Owner.
499	     *
500	     * @param name to test
501	     * @return true if pet name is already in use
502	     */
503	    public Pet getPet(String name, boolean ignoreNew) {
504	        name = name.toLowerCase();
505	        for (Pet pet : getPetsInternal()) {
506	            if (!ignoreNew || !pet.isNew()) {
507	                String compName = pet.getName();
508	                compName = compName.toLowerCase();
509	                if (compName.equals(name)) {
510	                    return pet;
511	                }
512	            }
513	        }
514	        return null;
515	    }
516	
517	    public Pet getPet(Integer petId) {
518	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
519	    }
520	
521	    @Override
522	    public String toString() {
523	        return new ToStringCreator(this)
524	
525	            .append("id", this.getId())
526	            .append("new", this.isNew())
527	            .append("lastName", this.getLastName())
528	            .append("firstName", this.getFirstName())
529	            .append("address", this.address)
530	            .append("city", this.city)
531	            .append("telephone", this.telephone)
532	            .toString();
533	    }
534	}
