266	    /**
267	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
268	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
269	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
270	     * a known region (see {@link Region}), the postcode must fall within that region's range
271	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
272	     * postcode.
273	     *
274	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
275	     */
276	    private void assertPostcodeValid(Owner owner) {
277	        String postcode = owner.getPostcode();
278	        if (postcode == null) {
279	            return;
280	        }
281	        String region = Region.forCity(owner.getCity());
282	        int[] range = region == null ? null : Region.postcodeRange(region);
283	        if (range == null) {
284	            return;
285	        }
286	        int value = Integer.parseInt(postcode);
287	        if (value < range[0] || value > range[1]) {
288	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
289	        }
290	    }
291	
292	    /**
293	     * Rejects saving {@code owner} when it carries a {@code registrationDate} later than the current
294	     * server date. The registration date is optional: a {@code null} date is left untouched (it is
295	     * defaulted to today by {@link #saveOwner(Owner)}). A registration cannot be dated in the future.
296	     *
297	     * @throws FutureRegistrationDateException if the supplied registration date is after today
298	     */
299	    private void assertRegistrationDateNotFuture(Owner owner) {
300	        LocalDate registrationDate = owner.getRegistrationDate();
301	        if (registrationDate == null) {
302	            return;
303	        }
