398	    /**
399	     * The owner's current primary identifier — the unified {@code memberId}. This is the single
400	     * place to switch so every consumer (notably the structured audit event) follows.
401	     */
402	    private String primaryIdentifier(Owner owner) {
403	        return owner.getMemberId();
404	    }
