406	    /**
407	     * Build a {@code memberId} formatted {@code '<REGION><FY><HASH8><CHK>'}: REGION is the region
408	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}); FY is
409	     * the two-digit fiscal year of the owner's (business-day-adjusted) {@code registrationDate} (see
410	     * {@link Owner#fiscalYearOf(LocalDate)}); HASH8 is the first 8 upper-case hex characters of the
411	     * SHA-256 digest over the concatenation of the owner's normalized telephone and {@code lastName};
412	     * and CHK is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}.
413	     * The telephone is already normalized and the registration date defaulted by
414	     * {@link #saveOwner(Owner)} before this runs. The layout is read back by
415	     * {@link Region#regionOfMemberId(String)}; keep the two in sync.
416	     */
417	    private String generateMemberId(Owner owner) {
418	        String region = Region.regionForPostcode(owner.getPostcode());
419	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
420	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
421	        String hash8 = Sha256Hex.upperHex(telephone + lastName, 8);
422	        LocalDate registrationDate = owner.getRegistrationDate();
423	        String fy = registrationDate == null
424	            ? "00" : String.format("%02d", Owner.fiscalYearOf(registrationDate) % 100);
425	        String base = region + fy + hash8;
426	        String memberId = base + luhnCheckDigit(base);
427	        return deduplicateMemberId(owner, memberId);
428	    }
429	
430	    /**
431	     * A single Luhn check digit (0-9) computed over the decimal digits contained in {@code value}
432	     * (non-digit characters, such as the region letters and hex letters, are ignored).
433	     */
434	    private static int luhnCheckDigit(String value) {
435	        int sum = 0;
436	        boolean dbl = true;
437	        for (int i = value.length() - 1; i >= 0; i--) {
438	            char c = value.charAt(i);
439	            if (c < '0' || c > '9') {
440	                continue;
441	            }
442	            int d = c - '0';
443	            if (dbl) {
444	                d *= 2;
445	                if (d > 9) {
446	                    d -= 9;
447	                }
448	            }
449	            sum += d;
450	            dbl = !dbl;
451	        }
452	        return (10 - (sum % 10)) % 10;
453	    }
454	
455	    /**
456	     * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
457	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
458	     * existing owners' {@code memberId}s. The {@code owner} being saved is excluded from the
459	     * comparison so re-saving it does not treat its own id as a collision.
460	     */
461	    private String deduplicateMemberId(Owner owner, String base) {
462	        Set<String> taken = new HashSet<>();
463	        for (Owner existing : ownerRepository.findAll()) {
464	            if (!existing.getId().equals(owner.getId()) && existing.getMemberId() != null) {
465	                taken.add(existing.getMemberId());
466	            }
467	        }
468	        if (!taken.contains(base)) {
469	            return base;
470	        }
471	        int n = 2;
472	        while (taken.contains(base + "-" + n)) {
473	            n++;
474	        }
475	        return base + "-" + n;
476	    }
