521	    /**
522	     * Rolls {@code date} forward to the next business day. A business day is Monday to Friday that is
523	     * not a listed public holiday; Saturdays, Sundays and public holidays are skipped by advancing
524	     * one day at a time until a business day is reached. Business days are returned unchanged.
525	     */
526	    private static LocalDate rollToBusinessDay(LocalDate date) {
527	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
528	            date = date.plusDays(1);
529	        }
530	        return date;
531	    }
