614	    /**
615	     * Normalizes whichever address fields {@code owner} supplied and derives the effective flat
616	     * {@code address} from them. The structured form is preferred: when a non-blank
617	     * {@code addressLine1} is present, {@code address} is set to the normalized {@code addressLine1},
618	     * with a single space and the normalized {@code addressLine2} appended when {@code addressLine2}
619	     * is present. Otherwise the flat {@code address} is normalized in place (backward-compatible). The
620	     * structured fields are also stored in their normalized form. Because everything downstream reads
621	     * {@link Owner#getAddress()}, the household hash, postcode validation and locality all see the
622	     * structured value when present and fall back to the flat address otherwise.
623	     */
624	    private static void applyAddress(Owner owner) {
625	        String line1 = normalizeAddress(owner.getAddressLine1());
626	        String line2 = normalizeAddress(owner.getAddressLine2());
627	        owner.setAddressLine1(line1);
628	        owner.setAddressLine2(line2);
629	        if (line1 != null && !line1.isEmpty()) {
630	            String composed = (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
631	            owner.setAddress(composed);
632	        } else if (owner.getAddress() != null) {
633	            owner.setAddress(normalizeAddress(owner.getAddress()));
634	        }
635	    }
