637	    /** Common street-type abbreviations expanded during address normalization. */
638	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
639	        "ST", "STREET",
640	        "RD", "ROAD",
641	        "AVE", "AVENUE");
642	
643	    /**
644	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
645	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
646	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
647	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
648	     * form.
649	     */
650	    private static String normalizeAddress(String address) {
651	        if (address == null) {
652	            return null;
653	        }
654	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
655	        if (collapsed.isEmpty()) {
656	            return "";
657	        }
658	        String[] tokens = collapsed.split(" ");
659	        StringBuilder sb = new StringBuilder(collapsed.length());
660	        for (int i = 0; i < tokens.length; i++) {
661	            if (i > 0) {
662	                sb.append(' ');
663	            }
664	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
665	        }
666	        return sb.toString();
667	    }
