673	    /**
674	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
675	     * that of another non-deleted owner. The key is the SHA-256 hex over the normalized telephone,
676	     * lower-cased email and {@code soundex(lastName)}, so it consolidates the former separate
677	     * telephone, email and household duplicate rules into a single check — only an exact full-key
678	     * match is a hard duplicate. Owners flagged {@link Owner#isDeleted() deleted} are ignored.
679	     *
680	     * @throws DuplicateIdentityException if another owner already has the same identity key
681	     */
682	    private void assertIdentityUnique(Owner owner) {
683	        String identityKey = owner.getIdentityKey();
684	        for (Owner existing : ownerRepository.findAll()) {
685	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
686	                    && identityKey.equals(existing.getIdentityKey())) {
687	                throw new DuplicateIdentityException(identityKey);
688	            }
689	        }
690	    }
691	
692	    /**
693	     * Flags {@code owner} as a soft match ({@link Owner#isPossibleDuplicate()} /
694	     * {@link Owner#getPossibleDuplicateOf()}) when its {@link Owner#getIdentityKey() identity key}
695	     * differs from every existing owner's (so it is not a hard duplicate) yet it shares an existing,
696	     * non-deleted owner's {@code soundex(lastName)} and {@code postcode}. This is what now admits two
697	     * owners with the same {@code lastName} and {@code postcode} but different telephones: they are
698	     * created as a soft match rather than rejected. The first matching owner (by store iteration
699	     * order) is recorded. Any prior flag is cleared first, and no match is possible when the owner
700	     * has no postcode or a last name that yields an empty soundex.
701	     */
702	    private void applySoftMatch(Owner owner) {
703	        owner.setPossibleDuplicate(false);
704	        owner.setPossibleDuplicateOf(null);
705	        String soundex = Soundex.encode(owner.getLastName());
706	        String postcode = owner.getPostcode();
707	        if (soundex.isEmpty() || postcode == null || postcode.isBlank()) {
708	            return;
709	        }
710	        String identityKey = owner.getIdentityKey();
711	        for (Owner existing : ownerRepository.findAll()) {
712	            if (existing.getId().equals(owner.getId()) || existing.isDeleted()) {
713	                continue;
714	            }
715	            if (!identityKey.equals(existing.getIdentityKey())
716	                    && soundex.equals(Soundex.encode(existing.getLastName()))
717	                    && postcode.equals(existing.getPostcode())) {
718	                owner.setPossibleDuplicate(true);
719	                owner.setPossibleDuplicateOf(existing.getId());
720	                return;
721	            }
722	        }
723	    }
724	
725	    /**
726	     * Assigns {@code owner} its deterministic {@code householdId}: the first 12 upper-case hex
727	     * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}, so all
728	     * owners that share a normalized {@code lastName} and {@code postcode} automatically share the
729	     * same household. Left {@code null} when either the lastName or the postcode is absent, since a
730	     * household is keyed on both.
731	     */
732	    private void assignHouseholdId(Owner owner) {
733	        String lastName = normalizeHouseholdValue(owner.getLastName());
734	        String postcode = owner.getPostcode();
735	        if (lastName.isEmpty() || postcode == null || postcode.isBlank()) {
736	            owner.setHouseholdId(null);
737	            return;
738	        }
739	        owner.setHouseholdId(generateHouseholdId(lastName, postcode));
740	    }
