742	    /**
743	     * Captures the membership-level ceiling for a newly created {@code owner}: its
744	     * {@link Owner#getMembershipLevel() membership level} may not exceed one above the highest level
745	     * among the household members (owners sharing its {@code householdId}) that already exist. When
746	     * the owner belongs to no household, or no existing member shares it, no cap applies and the
747	     * level is left uncapped. Each existing member's household size is stamped via
748	     * {@link #populateHouseholdSizes(Collection)} first so its level reflects the household-size
749	     * membership points.
750	     *
751	     * @see Owner#getMembershipLevelCap()
752	     */
753	    private void applyMembershipLevelCap(Owner owner) {
754	        owner.setMembershipLevelCap(null);
755	        String householdId = owner.getHouseholdId();
756	        if (householdId == null || householdId.isBlank()) {
757	            return;
758	        }
759	        List<Owner> members = new ArrayList<>();
760	        for (Owner existing : ownerRepository.findAll()) {
761	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
762	                    && householdId.equals(existing.getHouseholdId())) {
763	                members.add(existing);
764	            }
765	        }
766	        if (members.isEmpty()) {
767	            return;
768	        }
769	        populateHouseholdSizes(members);
770	        int maxLevel = 0;
771	        for (Owner member : members) {
772	            maxLevel = Math.max(maxLevel, member.getMembershipLevel());
773	        }
774	        owner.setMembershipLevelCap(maxLevel + 1);
775	    }
776	
777	    /**
778	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
779	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
780	     * reaching into the data store. A {@code null} owner or one without a household id is left at
781	     * size 0.
782	     */
783	    private void populateHouseholdSize(Owner owner) {
784	        if (owner == null) {
785	            return;
786	        }
787	        String householdId = owner.getHouseholdId();
788	        if (householdId == null || householdId.isBlank()) {
789	            owner.setHouseholdSize(0);
790	            return;
791	        }
792	        int count = 0;
793	        for (Owner existing : ownerRepository.findAll()) {
794	            if (householdId.equals(existing.getHouseholdId())) {
795	                count++;
796	            }
797	        }
798	        owner.setHouseholdSize(count);
799	    }
800	
801	    /**
802	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
803	     * store, so a list/page of owners is counted without a per-owner query.
804	     *
805	     * @see #populateHouseholdSize(Owner)
806	     */
807	    private void populateHouseholdSizes(Collection<Owner> owners) {
808	        if (owners.isEmpty()) {
809	            return;
810	        }
811	        Map<String, Integer> sizes = new HashMap<>();
812	        for (Owner existing : ownerRepository.findAll()) {
813	            String householdId = existing.getHouseholdId();
814	            if (householdId != null && !householdId.isBlank()) {
815	                sizes.merge(householdId, 1, Integer::sum);
816	            }
817	        }
818	        for (Owner owner : owners) {
819	            String householdId = owner.getHouseholdId();
820	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
821	        }
822	    }
823	
824	    /**
825	     * Derives the deterministic {@code householdId} from the normalized {@code lastName} and
826	     * {@code postcode}: the first 12 upper-case hex characters of SHA-256 over
827	     * {@code lastName + '|' + postcode}, so all owners in the same household share the same
828	     * identifier.
829	     */
830	    private static String generateHouseholdId(String lastName, String postcode) {
831	        return Sha256Hex.upperHex(lastName + "|" + postcode, 12);
832	    }
