834	    /**
835	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
836	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
837	     */
838	    private static String normalizeHouseholdValue(String value) {
839	        if (value == null) {
840	            return "";
841	        }
842	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
843	    }
