862	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
863	    }
864	
865	    private <T> T findEntityById(Supplier<T> supplier) {
866	        try {
867	            return supplier.get();
868	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
869	            // Just ignore not found exceptions for Jdbc/Jpa realization
870	            return null;
871	        }
872	    }
